cssHead:
body {
  font-family: 'Geist', sans-serif;
  background-color: #F9FAF7;
  color: #203E35;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}


/* 3D Sage Green Glossy Sphere Logo */
.glossy-sphere {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #92b8a7, #4b7361 65%, #2a473b 100%);
  box-shadow: 0 3px 6px -1px rgba(32, 62, 53, 0.28), inset 0 -2px 4px rgba(0, 0, 0, 0.25);
}
